-- Struktur Tabel: `arsip_surat_masuk`
-- ---------------------------------------------------------
DROP TABLE IF EXISTS `arsip_surat_masuk`;
CREATE TABLE `arsip_surat_masuk` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nomor_agenda` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nomor_surat` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal_surat` date NOT NULL,
  `tanggal_diterima` date NOT NULL,
  `asal_instansi` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `perihal` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ringkasan_isi` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sifat_surat` enum('BIASA','PENTING','SEGERA','KILAT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BIASA',
  `file_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cloudinary_public_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `drive_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_name_original` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_size_bytes` bigint DEFAULT '0',
  `indexed_by` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `uk_arsip_sm_agenda` (`nomor_agenda`),
  KEY `idx_arsip_sm_tgl_terima` (`tanggal_diterima`),
  KEY `idx_arsip_sm_instansi` (`asal_instansi`),
  KEY `idx_arsip_sm_sifat` (`sifat_surat`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

